const M=MiniChess, q=s=>document.querySelector(s);let game=M.create(),selected=null,flipped=false,logs=[],blueFirst=Math.random()<.5;
const names={K:'킹',R:'룩',B:'비숍',P:'폰',G:'승급 폰'},glyph={K:'♚',R:'♜',B:'♝',P:'♟',G:'♟'};
const color=p=>(p===0)===blueFirst?'블루':'퍼플', colorClass=p=>color(p)==='블루'?'blue-piece':'purple-piece';
const pos=i=>'ABC'[i%3]+(4-Math.floor(i/3));
const pieceHTML=(t,p,facing=false)=>`<span class="piece ${colorClass(p)} ${facing?'enemy-facing':''}"><span class="glyph">${glyph[t]}</span><span class="piece-name">${names[t]}</span></span>`;
function selectedActions(){if(!selected)return [];return M.actions(game).filter(a=>selected.drop?a.drop===selected.drop:a.from===selected.from)}
function render(){let result=game.result,turn=game.turn;let text=result?(result.winner===null?'무승부':color(result.winner)+' 승리'):color(turn)+' 차례';q('#turn-info').innerHTML=`<div class="turn-banner ${result?'finished':color(turn)==='퍼플'?'purple':''}"><strong>${text}</strong><small>${result?result.reason:(turn===0?'선공':'후공')+' · 앞으로 '+((turn===0)!==flipped?'↑':'↓')}</small></div>${game.pending!==null&&!result?`<div class="alert-line">${color(game.pending)} 킹 진입! 이번 차례에 잡지 못하면 ${color(game.pending)} 승리합니다.</div>`:''}`;
let candidates=selectedActions(),order=Array.from({length:12},(_,i)=>flipped?11-i:i);q('#chess-board').innerHTML=order.map(i=>{let pc=game.board[i],target=candidates.some(a=>a.to===i),chosen=selected?.from===i,danger=pc?.t==='K'&&M.threatened(game,i),facing=pc&&((pc.p===1)!==flipped);return `<button class="square ${(Math.floor(i/3)+i%3)%2?'alt':''} ${target?(pc?'capture':'target'):''} ${chosen?'chosen':''}" data-cell="${i}" aria-label="${pos(i)} ${pc?color(pc.p)+' '+names[pc.t]:'빈칸'}${target?' · '+(pc?'포획 가능':'이동 가능'):''}${danger?' · 킹 위험':''}" ${result?'disabled':''}><span class="coord">${pos(i)}</span>${pc?pieceHTML(pc.t,pc.p,facing):target?'·':''}${danger?'<span class="mark" title="공격받는 킹">!</span>':''}${pc?.t==='G'?'<span class="promotion">승급</span>':''}</button>`}).join('');
renderHand('#top-hand',flipped?0:1);renderHand('#bottom-hand',flipped?1:0);q('#count').textContent=`${game.ply}/100차례`;q('#move-log').innerHTML=logs.length?logs.map(x=>`<li>${x}</li>`).join(''):'<li>말을 선택해 첫 수를 두세요.</li>';q('#resign').disabled=!!result;
let king=game.board.findIndex(pc=>pc?.p===turn&&pc.t==='K');q('#hint').textContent=result?`${text} · ${result.reason}. 새 경기로 다시 시작할 수 있습니다.`:selected?(selected.drop?`${names[selected.drop]} 재투입: 표시된 빈칸을 선택하세요.`:`${names[game.board[selected.from].t]}: 표시된 칸을 선택하세요.`):`${color(turn)}의 말 또는 보유 말을 선택하세요.${king>=0&&M.threatened(game,king)?' ⚠ 내 킹이 공격받고 있습니다.':''}`;
q('#chess-board').querySelectorAll('[data-cell]').forEach(b=>b.addEventListener('click',()=>chooseCell(Number(b.dataset.cell))));}
function renderHand(selector,p){let h=game.hands[p];q(selector).innerHTML=`<span class="pocket-title ${colorClass(p)}"><b>${color(p)} 보유 말</b></span>${h.length?[...new Set(h)].map(t=>`<button class="hand-piece ${colorClass(p)} ${p===game.turn&&selected?.drop===t?'chosen':''}" data-drop="${t}" aria-label="${color(p)} ${names[t]} 재투입" ${game.result||p!==game.turn?'disabled':''}><span class="glyph">${glyph[t]}</span><small>×${h.filter(x=>x===t).length}</small></button>`).join(''):'<span class="empty-hand">잡은 말이 없습니다</span>'}`;q(selector).querySelectorAll('[data-drop]').forEach(b=>b.addEventListener('click',()=>{selected=selected?.drop===b.dataset.drop?null:{drop:b.dataset.drop};render()}))}
function chooseCell(i){if(game.result)return;let action=selectedActions().find(a=>a.to===i);if(action){let out=M.apply(game,action),e=out.event;logs.push(`${color(e.p)} · ${names[e.moved]} ${e.drop?'보유 말 → ':pos(e.from)+' → '}${pos(e.to)}${e.captured?' · '+names[e.captured]+' 포획':''}${e.promoted?' · 승급':''}`);game=out.state;selected=null;render();return}if(game.board[i]?.p===game.turn){selected=selected?.from===i?null:{from:i};render()}else{q('#hint').textContent='이 칸으로 이동할 수 없습니다. 자기 말이나 표시된 칸을 선택하세요.'}}
q('#rotate').addEventListener('click',()=>{flipped=!flipped;render()});q('#restart').addEventListener('click',()=>{if(!game.result&&game.ply>0&&!confirm('현재 경기를 끝내고 새 경기를 시작할까요?'))return;blueFirst=!blueFirst;game=M.create();selected=null;logs=[];render()});q('#resign').addEventListener('click',()=>{if(game.result||!confirm(color(game.turn)+' 플레이어가 기권할까요?'))return;game.result={winner:1-game.turn,reason:color(game.turn)+' 기권'};selected=null;render()});q('#rules-open').addEventListener('click',()=>q('#rules').showModal());q('#rules-close').addEventListener('click',()=>q('#rules').close());
q('#move-guide').innerHTML=[['K','모든 방향 1칸'],['R','상하좌우 1칸'],['B','대각선 1칸'],['P','앞으로 1칸 · 이동과 포획 동일'],['G','6방향 1칸 · 뒤쪽 대각선 제외']].map(([t,text])=>`<div class="guide-row"><span>${glyph[t]}</span><b>${names[t]}</b><small>${text}</small></div>`).join('');render();
